/**
 * Lee un texto con el importador que le toca y, cuando el papel no tiene un
 * tipo propio claro (una factura, un justificante cualquiera), deja que el
 * clasificador de siempre afine el tipo. Si ese clasificador nombra un tipo
 * que tiene lector propio (nómina, liquidación, subvención…), el documento se
 * vuelve a leer entero con él, para que no salga a medias.
 */
async function leerTextoDocumento(text, fileName) {
  const opciones = { defaultRate: getState().settings.defaultRate, fileName };
  let lectura = leerDocumento(text, opciones);
  let cls = null;
  if (!lectura.generico) return { lectura, cls };

  cls = await classifyDocument(text, getState().settings, { fileName });
  if (cls.kind && cls.kind !== lectura.doc.kind) {
    const otra = leerDocumento(text, { ...opciones, tipo: cls.kind });
    if (otra.reconoce) return { lectura: otra, cls: null };
    lectura.doc.kind = cls.kind;
    lectura.doc.direction = cls.direction || directionOf(cls.kind);
  }
